1	/* =====================================================================
2	   HEARD — Design System Foundations
3	   Companionship marketplace. Warm, trustworthy, accessible-first.
4	   Body text ≥ 18px. Contrast AA floor, AAA on body where feasible.
5	   ===================================================================== */
6	
7	/* ---- Fonts ---------------------------------------------------------- */
8	/* Nunito (display/headings) + Nunito Sans (body). Humanist, rounded,
9	   highly legible — chosen for an older / low-vision audience.
10	   Loaded via Google Fonts CDN. See README "Typography". */
11	@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Nunito+Sans:opsz,wght@6..12,400;6..12,600;6..12,700&display=swap');
12	
13	:root {
14	  /* ---- Color: brand palette (exact tokens from brief) ------------- */
15	  --bg:            #FBF7F2;  /* warm off-white page background          */
16	  --surface:       #FFFFFF;  /* cards, sheets                          */
17	  --surface-sunk:  #F4EEE5;  /* recessed wells, track backgrounds      */
18	
19	  --ink:           #2A2622;  /* primary text (warm near-black)         */
20	  --ink-soft:      #6B6259;  /* secondary text                        */
21	  --ink-faint:     #948B81;  /* tertiary / placeholder                 */
22	
23	  --primary:       #136F63;  /* calm teal — trust; primary buttons     */
24	  --primary-dark:  #0E5249;  /* hover / active                        */
25	  --primary-tint:  #E4EFEC;  /* teal wash — selected chips, fills      */
26	
27	  --accent:        #E08A3C;  /* warm amber — tips, gentle highlights   */
28	  --accent-dark:   #C4732C;  /* amber hover / active                   */
29	  --accent-tint:   #FBEBD9;  /* amber wash                            */
30	
31	  --success:       #2E7D5B;  /* available / positive (pair w/ text)    */
32	  --success-tint:  #E3F0EA;
33	  --alert:         #B23A2E;  /* errors / safety (pair w/ text)         */
34	  --alert-tint:    #F7E6E3;
35	
36	  --border:        #ECE3D8;  /* hairlines, dividers                    */
37	  --border-strong: #D9CCBC;  /* input borders, stronger separation     */
38	  --focus:         #1B6FB0;  /* high-visibility focus ring (3px)       */
39	
40	  /* ---- Type families --------------------------------------------- */
41	  --font-display: 'Lora', Georgia, 'Times New Roman', serif;  /* warm humanist serif — headings */
42	  --font-body:    'Nunito Sans', system-ui, -apple-system, sans-serif;
43	
44	  /* ---- Type scale (px). Body floor = 18px ------------------------ */
45	  --text-xs:   14px;   /* meta / fine print — use sparingly          */
46	  --text-sm:   16px;   /* labels, secondary                         */
47	  --text-base: 18px;   /* BODY MINIMUM                              */
48	  --text-lg:   20px;   /* large body / lead                         */
49	  --text-h3:   24px;
50	  --text-h2:   30px;
51	  --text-h1:   38px;
52	  --text-display: 46px;
53	
54	  --leading-tight: 1.2;
55	  --leading-snug:  1.35;
56	  --leading-body:  1.6;   /* generous body line-height               */
57	
58	  --weight-regular: 400;
59	  --weight-semibold: 600;
60	  --weight-bold: 700;
61	  --weight-extrabold: 800;
62	
63	  /* ---- Spacing — 8px grid ---------------------------------------- */
64	  --space-1: 4px;
65	  --space-2: 8px;
66	  --space-3: 12px;
67	  --space-4: 16px;
68	  --space-5: 24px;
69	  --space-6: 32px;
70	  --space-7: 48px;
71	  --space-8: 64px;
72	  --space-9: 96px;
73	
74	  /* ---- Radii ----------------------------------------------------- */
75	  --radius-sm:   8px;
76	  --radius-btn:  12px;   /* buttons                                  */
77	  --radius-card: 16px;   /* cards, sheets                            */
78	  --radius-lg:   24px;   /* large surfaces / hero                    */
79	  --radius-pill: 999px;  /* chips, toggles, avatars                  */
80	
81	  /* ---- Shadows — soft, low, warm --------------------------------- */
82	  --shadow-xs: 0 1px 2px rgba(42, 38, 34, 0.05);
83	  --shadow-sm: 0 2px 8px rgba(42, 38, 34, 0.06);
84	  --shadow-md: 0 6px 20px rgba(42, 38, 34, 0.08);
85	  --shadow-lg: 0 14px 40px rgba(42, 38, 34, 0.12);
86	
87	  /* ---- Focus ring — never removed -------------------------------- */
88	  --focus-ring: 0 0 0 3px var(--focus);
89	  --focus-ring-offset: 0 0 0 2px var(--surface), 0 0 0 5px var(--focus);
90	
91	  /* ---- Min interactive target ------------------------------------ */
92	  --tap-min: 48px;
93	
94	  /* ---- Motion (gentle; respect reduced-motion) ------------------- */
95	  --ease: cubic-bezier(0.33, 0.1, 0.25, 1);
96	  --dur-fast: 120ms;
97	  --dur: 200ms;
98	  --dur-slow: 320ms;
99	}
100	
101	/* =====================================================================
102	   SEMANTIC ELEMENT DEFAULTS
103	   Drop colors_and_type.css into any page to get on-brand baselines.
104	   ===================================================================== */
105	
106	body {
107	  background: var(--bg);
108	  color: var(--ink);
109	  font-family: var(--font-body);
110	  font-size: var(--text-base);
111	  line-height: var(--leading-body);
112	  font-weight: var(--weight-regular);
113	  -webkit-font-smoothing: antialiased;
114	  text-rendering: optimizeLegibility;
115	}
116	
117	h1, h2, h3, h4 {
118	  font-family: var(--font-display);
119	  color: var(--ink);
120	  line-height: var(--leading-tight);
121	  text-wrap: balance;
122	  margin: 0;
123	}
124	h1 { font-size: var(--text-h1); font-weight: 700; letter-spacing: -0.01em; }
125	h2 { font-size: var(--text-h2); font-weight: 700; letter-spacing: -0.01em; }
126	h3 { font-size: var(--text-h3); font-weight: var(--weight-bold); }
127	
128	p  { margin: 0; text-wrap: pretty; }
129	.lead { font-size: var(--text-lg); color: var(--ink-soft); line-height: var(--leading-body); }
130	.meta { font-size: var(--text-sm); color: var(--ink-soft); }
131	
132	a { color: var(--primary); text-underline-offset: 3px; }
133	a:hover { color: var(--primary-dark); }
134	
135	/* ---- Universal visible focus — the single most important rule ----- */
136	:where(a, button, input, select, textarea, [tabindex], [role="button"], [role="tab"]):focus-visible {
137	  outline: none;
138	  box-shadow: var(--focus-ring);
139	  border-radius: var(--radius-sm);
140	}
141	
142	@media (prefers-reduced-motion: reduce) {
143	  *, *::before, *::after {
144	    animation-duration: 0.001ms !important;
145	    animation-iteration-count: 1 !important;
146	    transition-duration: 0.001ms !important;
147	  }
148	}
